import{_ as s,o as t,c as a,a0 as o}from"./chunks/framework.1R7PBCUH.js";const n="/computer-fundamentals/assets/overview.B4r2rgp2.png",i="/computer-fundamentals/assets/layout.D-2UYTqD.png",p="/computer-fundamentals/assets/activities_overview.W-UB8QHZ.png",r="/computer-fundamentals/assets/launch_app.CyQ2duha.png",l="/computer-fundamentals/assets/applications_overview.DDjTnKSp.png",h="/computer-fundamentals/assets/top_bar.BjWQ3pZU.png",d="/computer-fundamentals/assets/system_status_area.BWPzKovK.png",c="/computer-fundamentals/assets/terminal.B_VYqmfk.png",w=JSON.parse('{"title":"Exploring Ubuntu","description":"","frontmatter":{},"headers":[],"relativePath":"labs/exploring-ubuntu.md","filePath":"labs/exploring-ubuntu.md"}'),u={name:"labs/exploring-ubuntu.md"};function m(g,e,k,b,v,y){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="exploring-ubuntu" tabindex="-1">Exploring Ubuntu <a class="header-anchor" href="#exploring-ubuntu" aria-label="Permalink to &quot;Exploring Ubuntu&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This lab is still in draft. It contains all the information you need, but the text isn&#39;t polished yet.</p></div><p>Ubuntu is a popular and easy to use distribution for new Linux users. It provides a familiar and welcoming desktop environment for users switching from Windows or macOS.</p><p>In this lab, you&#39;ll explore Ubuntu. You&#39;ll start with the desktop environment, then move on to the command line.</p><h2 id="the-desktop-environment" tabindex="-1">The desktop environment <a class="header-anchor" href="#the-desktop-environment" aria-label="Permalink to &quot;The desktop environment&quot;">​</a></h2><p>Ubuntu&#39;s desktop environment is based on <a href="https://www.gnome.org" target="_blank" rel="noreferrer">GNOME</a>, one of two major desktop environments for Linux (the other being <a href="https://kde.org" target="_blank" rel="noreferrer">KDE</a>).</p><p>The default desktop layout looks like this:</p><p><img src="'+n+'" alt="Default desktop"></p><p>This layout places important panels and controls along the top and left sides of the screen. The screenshot below outlines these in red:</p><p><img src="'+i+'" alt="Desktop layout"></p><p>The most important control is in the top left. This button opens the <strong>Activities Overview</strong>, the central hub of the desktop:</p><p><img src="'+p+'" alt="Activities overview"></p><p>From here, you can type to search for applications and launch them:</p><p><img src="'+r+'" alt="Launching an app"></p><p>The Activities Overview also shows an overview of your workspaces — virtual desktops that group windows. You can navigate between workspaces, drag windows around, and so on. The “Activies Overview” button doubles as an indicator for the active workspace.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Although the “Activities Overview” button is always present, you&#39;ll usually open the Activities Overview by pressing the <code>Super</code> key, which is the key with the Windows logo, or the <code>Command</code> key on Apple hardware, provided that your hypervisor didn&#39;t reassign this key.</p></div><p>On the left side of the screen is the <strong>Dock</strong>, which is where you can see your open applications and pin the ones you use most often.</p><p>At the end of the dock is a button that opens the <strong>Applications Overview</strong>. This screen displays a grid of your installed applications. It also offers some of the features of the Activities Overview:</p><p><img src="'+l+'" alt="Applications overview"></p><p>Finally, the top of the screen is taken up by the <strong>Top Bar</strong>, which displays various controls and indicators. Click the current date and time to see your calendar and notifications:</p><p><img src="'+h+'" alt="Calendar and notifications"></p><p>The Top Bar also displays the <strong>System Status Area</strong>. Click this area to open the <strong>Quick Settings</strong> panel:</p><p><img src="'+d+'" alt="System status area"></p><p>This panel includes a button to power off the virtual machine. Use this button to perform a proper shutdown. This is much safer than closing the hypervisor&#39;s window, which could leave the machine in an invalid state.</p><h2 id="using-the-command-line" tabindex="-1">Using the command line <a class="header-anchor" href="#using-the-command-line" aria-label="Permalink to &quot;Using the command line&quot;">​</a></h2><p>An average Linux user will spend most of their time in the desktop environment, browsing the web, using office productivity apps, or playing games. However, the real power of Linux comes from the <strong>command line</strong>. This textual interface is where you type commands to manage the system, install and update software, automate workflows, and connect to remote servers.</p><p>Textual interfaces are how computers used to work before they had graphical interfaces, and they&#39;re still the most powerful tool available to a system administrator.</p><p>On Ubuntu, you access the command line through the <strong>Terminal</strong> application:</p><p><img src="'+c+`" alt="Terminal"></p><p>The terminal gives you access to a <strong>shell</strong>, which is the program that processes your commands. The default shell on Ubuntu is <strong>Bash</strong>. When you open a terminal, Bash will show a <strong>prompt</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">steven@Linux:~$</span></span></code></pre></div><p>This prompt contains the following information:</p><ul><li>My username, “steven”.</li><li>The hostname of my virtual machine, “Linux”.</li><li>The current directory, “~”, which refers to my home directory.</li></ul><p>The prompt provides important contextual information. You can use the command line to navigate your system, sign in as a different user, and connect to other systems, so it&#39;s important to keep track of who and where you are.</p><p>The prompt uses an at sign (<code>@</code>) and colon (<code>:</code>) as separators and ends in a dollar sign (<code>$</code>). Type your command after this prompt, then press <code>Enter</code> to send it.</p><p>Try sending the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span></span></code></pre></div><p>This command lists the contents of the current directory, in this case, your home directory.</p><p>Commands can take <strong>arguments</strong> to specify the files or directories they operate on. For example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Downloads</span></span></code></pre></div><p>This command lists the contents of the <strong>Downloads</strong> directory.</p><p>Commands can take multiple arguments:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Downloads</span></span></code></pre></div><p>This command lists the contents of both the <strong>Desktop</strong> and the <strong>Downloads</strong> directory.</p><p>Commands also have <strong>options</strong> that configure their behavior. You specify an option as a dash sign (<code>-</code>) followed by a letter:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre></div><p>Here, option <code>-l</code> causes <code>ls</code> to use a longer, more detailed, output format.</p><p>Keep in mind that options are case-sensitive. The following command will not work:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span></span></code></pre></div><p>Option <code>-L</code> may have a different meaning than <code>-l</code>, or in this case, no meaning at all.</p><p>You can specify multiple options, either separately, or grouped behind a single dash:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span></span></code></pre></div><p>These commands are equivalent and add the option <code>-h</code> to print file sizes in a human-readable format. Most options can be grouped in this way, and the order in which you specify them usually doesn&#39;t matter.</p><p>However, some options have longer names and cannot be grouped. You specify these options with a double dash:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --human-readable</span></span></code></pre></div><p>In this case, <code>--human-readable</code> is equivalent to <code>-h</code>. The former is easier to understand, but the latter is easier to type.</p><p>Of course, options and arguments can be used together. A full command could look like this:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Downloads</span></span></code></pre></div><p>This command lists the contents of the <strong>Downloads</strong> directory using a long output format with human-readable sizes.</p><h2 id="up-next" tabindex="-1">Up next <a class="header-anchor" href="#up-next" aria-label="Permalink to &quot;Up next&quot;">​</a></h2><p>This lab gave you a short tour of the Ubuntu operating system. The desktop environment should feel familiar to you, but the command line may take some getting used to.</p><p>All remaining labs will focus exclusively on using the command line. By the end of this course, you should feel at home in the terminal, and you&#39;ll come to understand and appreciate the power of the command line.</p><p>Complete the upcoming exercises, then continue on to the next lab, where you&#39;ll learn to manage files and directories from the command line.</p>`,63)])])}const C=s(u,[["render",m]]);export{w as __pageData,C as default};
